void check_dummy_password_v16(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if ((mask & KADM5_ATTRIBUTES) && (entry->attributes & KRB5_KDB_ATR_DUMMY)) {
        if (*passptr && (strlen(*passptr) > 0 && strlen(*passptr) <= 255)) {
            *passptr = NULL;
        }
    }
}

void check_dummy_password_v1_6(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if ((mask & KADM5_ATTRIBUTES) && (entry->attributes & KRB5_KDB_AUX_OLDFORMAT)) {
        return;
    }

    if ((mask & KADM5_ATTRIBUTES) && (entry->attributes & KRB5_KDB_AUX_RANDKEY)) {
        return;
    }

    if (n_ks_tuple <= 0 || ks_tuple == NULL) {
        return;
    }

    if (*passptr == NULL || strlen(*passptr) == 0) {
        return;
    }

    size_t len = strlen(*passptr);
    if (len >= 1 && len <= 255) {
        *passptr = NULL;
    }
}

void check_dummy_password_v1_6(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if ((mask & KADM5_ATTRIBUTES) == 0 || (entry->attributes & KRB5_KDB_ATTRIBUTES_ETYPE_AES) == 0) {
        return;
    }

    if (*passptr == NULL) {
        return;
    }

    size_t len = strlen(*passptr);
    if (len >= 1 && len <= 255) {
        char *password = *passptr;
        for (size_t i = 0; i < len; i++) {
            if ((unsigned char)password[i] > 0xff) {
                return;
            }
        }
        *passptr = NULL;
    }
}

void check_dummy_password(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if ((entry->attributes & KADM5_AUX_ATTRIBUTES) == 0 || (mask & KADM5_AUX_ATTRIBUTES) == 0) {
        return;
    }

    if (passptr && *passptr) {
        size_t len = strlen(*passptr);
        if (len >= 1 && len <= 255) {
            *passptr = NULL;
        }
    }
}

void check_dummy_password_v1_6(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if ((mask & KADM5_ATTRIBUTES) == 0 || (entry->attributes & KRB5_KDB_AUX_OLDTYPE) == 0) {
        return;
